
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_m08_so_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_m08_so", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.117817880622653e-02, -1.830220888874904e-02, -1.603729915946002e-02, -1.669700111987904e-02, -2.491791912843591e-02, -4.628422909548746e-02, -7.558028230977086e-02, -7.145140895790035e-02, 3.921517473902929e-03, 5.064461372386146e-02, 3.578530792932675e-02, -6.798614720318706e-02, -4.706472655923466e-02, -3.172085472883777e-02, 6.328368037882041e-03, 9.694765373122638e-03, -4.345158235116546e-02, -4.249903122755749e-02, -1.329817194409967e-02, -1.904512257965136e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


